params.command:
$ErrorActionPreference='Continue'
$relay=Join-Path $env:USERPROFILE 'HeavenBridgeRepo'
$tmp=Join-Path $env:USERPROFILE 'mhw-safe-branch-delete2'
if (Test-Path $tmp) { Remove-Item -Recurse -Force $tmp }
$url=(git -C $relay remote get-url origin).Trim()
git clone --no-local $relay $tmp | Out-Null
git -C $tmp remote set-url origin $url
git -C $tmp fetch origin '+refs/heads/*:refs/remotes/origin/*' --prune | Out-Null
$deleted=@(); $kept=@(); $failed=@()
$branches=git -C $tmp for-each-ref --format='%(refname:short)' refs/remotes/origin | Where-Object { $_ -ne 'origin' -and $_ -ne 'origin/HEAD' }
foreach($rb in $branches){
  $b=$rb -replace '^origin/',''
  if($b -in @('main','heaven-bridge')) { continue }
  $branchOnlyText=(git -C $tmp rev-list --right-only --count "origin/main...origin/$b" 2>$null)
  if($LASTEXITCODE -ne 0){ $failed += [pscustomobject]@{branch=$b;error='rev-list-failed'}; continue }
  $branchOnly=[int]($branchOnlyText.Trim())
  if($branchOnly -eq 0){
    git -C $tmp push origin ":refs/heads/$b" *> $null
    if($LASTEXITCODE -eq 0){ $deleted += $b } else { $failed += [pscustomobject]@{branch=$b;error='remote-delete-failed'} }
  } else {
    $kept += [pscustomobject]@{branch=$b;unique_commits=$branchOnly}
  }
}
git -C $tmp fetch origin --prune | Out-Null
[pscustomobject]@{deleted=$deleted;deleted_count=$deleted.Count;kept=$kept;kept_count=$kept.Count;failed=$failed;failed_count=$failed.Count} | ConvertTo-Json -Depth 6 -Compress
